insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-07','verbeterd','Meerwerk','Meerwerk en stelposten staan vanzelf in Bouw7',
   'Meerwerkregels die nog niet in Bouw7 stonden, ook oudere, zet EVA daar nu zelf neer. Lukt het een keer niet, dan probeert EVA het bij de volgende synchronisatie opnieuw. Een stelpost die buiten de aanneemsom valt komt in Bouw7 als meerwerk met "stelpost" aangevinkt.');
